 232	        0,
 233	        0,
 234	        @intCast(self.width),
 235	        @intCast(self.height),
 236	        .rgba,
 237	        .unsigned_byte,
 238	        pixels.ptr,
 239	    );
 240	
 241	    return pixels;
 242	}

